function build(byPlace) {
  // A follow-up named only in an option's wording shows where its parent does.
  const varsOf = Object.fromEntries(Object.values(byPlace).flat().map((r) => [r[0], r[3].split(" ")]));
  const fields = Object.entries(byPlace).flatMap(([place, rows]) =>
    rows.map((row) => {
      // A sixth element would be silently ignored (2026-11-27: five rows lost
      // their state help and one Indiana limit that way).
      if (row.length > 5) throw new Error(`clauseFields: ${row[0]} has ${row.length} elements; merge the extras into one object`);
      const [id, type, label, vars, extra = {}] = row;
      const list = vars.split(" ");
      const named = list.some((v) => statesByVariable[v]) ? list : varsOf[extra.showIf?.id] || [];
      const states = [...new Set(named.flatMap((v) => [...(statesByVariable[v] || [])]))].sort();
      return {
        id, type, label, short: label.replace(/\?$/, ""), place, section: "Clause fields", counts: false,
        states, vars: list, ...extra, ...(place === "lease.clause" ? { builderOnly: true } : {}),
      };
    }),
  );
  // A follow-up another state reuses keeps its parent's condition only where
  // that parent is asked (`showIf.states`); elsewhere it always shows
  // (2026-11-27: New York reuses Montana's condominium unit questions).
  const byId = Object.fromEntries(fields.map((q) => [q.id, q]));
  for (const q of fields) {
    const parent = q.showIf && byId[q.showIf.id];
    if (parent && q.states.some((st) => !parent.states.includes(st))) q.showIf = { ...q.showIf, states: parent.states };
  }
  return fields;
}

module.exports = { PROPERTY_FIELDS: build(PROPERTY), LEASE_FIELDS: build(LEASE) };
